steps.script:
$cid='tr-autoguard-1794486419'
$o=@{command_id=$cid;phase_codes=@();error_codes=@();matched_lines=0;launcher_logs=0;guard_sha256='';wrapper_marker=$false;guard_known_markers=@();task_state='unknown';node_available=$false}
try {
 $base='C:\TTiTTulares'
 $p=Join-Path $base 'ttendencias-mobile-trigger.log'
 if(Test-Path -LiteralPath $p){
  $lines=@(Get-Content -LiteralPath $p -Tail 1800 -ErrorAction Stop|Where-Object{$_.Contains($cid)})
  $o.matched_lines=$lines.Count
  $pattern='PROCESS START ERROR|CHAT LAUNCH LOG ERROR|CHAT PROCESS EXITED|LAUNCH ERROR|LAUNCH NOT CONFIRMED|CHAT MESSAGE TIMEOUT|CHAT MESSAGE CONFIRMED|ACK 409 BYPASSED|ACK CONFLICT|EDITORIAL TARGET|PROCESS STARTED'
  foreach($l in $lines){
   $m=[regex]::Match([string]$l,$pattern)
   if($m.Success){$o.phase_codes+= $m.Value}
  }
 }
 $logfiles=@(Get-ChildItem -LiteralPath $base -Filter 'ttendencias-launch-*.log' -File -ErrorAction SilentlyContinue|Sort-Object LastWriteTimeUtc -Descending|Select-Object -First 30)
 foreach($file in $logfiles) {
  $raw=Get-Content -LiteralPath $file.FullName -Raw -ErrorAction SilentlyContinue
  if(-not $raw){continue}
  if($raw.Contains($cid) -or $file.LastWriteTimeUtc -ge [datetime]'2026-11-12T12:26:00Z') {
   $o.launcher_logs++
   foreach($m in [regex]::Matches($raw,'(?i)TT_GUARD ERROR|NEW_CHAT_NOT_BLANK|NEW_CHAT_CONTROL_UNAVAILABLE|RESTORED_DRAFT_[A-Z_]+|TOO_MANY_TABS[A-Z_]*|OTHER_CHAT_ACTIVITY|NO_PROBE|COMPOSER_NOT_READY|No aparece el cuadro de escritura|PROJECT_EDITOR_UNAVAILABLE|AMBIGUOUS_PREVIOUS_SEND|TRANSMISSION_UNVERIFIED|DRAFT_NOT_[A-Z_]+|ERROR:|Timeout CDP|PROCESS START ERROR|CHATGPT|EJECUCION LANZADA|MENSAJE ENVIADO|MODO: PRUEBA|MODO: ENVIO REAL|EXCEPTION|TypeError|ReferenceError|SyntaxError|ERR_[A-Z_]+')) {
    $v=$m.Value.ToUpperInvariant()
    if($o.error_codes -notcontains $v){$o.error_codes+=$v}
   }
  }
 }
 $g=Join-Path $base 'TT-Editorial-Guard.js'
 if(Test-Path -LiteralPath $g){
  $o.guard_sha256=(Get-FileHash -LiteralPath $g -Algorithm SHA256).Hash.ToLowerInvariant()
  $s=Get-Content -LiteralPath $g -Raw -ErrorAction SilentlyContinue
  foreach($k in @('FAILED_OWNED_PRUNE','RESTORED_DRAFT_BACKED_UP_LOCAL','NEW_CHAT_NOT_BLANK','--inspect-failed','--probe','placeholderMatch')){if($s.Contains($k)){$o.guard_known_markers+=$k}}
 }
 $w=Join-Path $base 'Ejecutar.js';if(Test-Path -LiteralPath $w){$o.wrapper_marker=(Get-Content -LiteralPath $w -Raw -ErrorAction SilentlyContinue).Contains('TT_EDITORIAL_SAFE_WRAPPER_V1')}
 $n=Get-Command node.exe -ErrorAction SilentlyContinue; $o.node_available=($null -ne $n)
 $t=Get-ScheduledTask -TaskName 'TTendencias Local' -ErrorAction SilentlyContinue
 if($t){$o.task_state=[string]$t.State}
}catch{$o.error_category='DIAGNOSTIC_EXCEPTION'}
$o.phase_codes=@($o.phase_codes|Select-Object -Unique)
$o.error_codes=@($o.error_codes|Select-Object -Unique)
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress -Depth 5))
